        {"quote": "config.json is read, README.md may be inspected, and config-note.md is produced.", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "Neither file", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "modify",
      "verdict": "SUPPORT",
      "reason": "'Neither file may be modified' prohibits modification of each file in the unresolved pair. FORBIDDEN represents the negative permission without requiring a second negation on the event.",
      "sources": [{"quote": "Neither file may be modified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_pm",
      "verdict": "SUPPORT",
