      "sources": [{"quote": "PM must organize", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r_task",
      "verdict": "CONTRADICT",
      "reason": "'The task' is the object of organizing, not an asserted whole containing the organizing event. PART_OF also cannot take a TASK endpoint under the supplied signature; if TASK is a reserved root, that does not supply the missing object binding.",
